from __future__ import absolute_import
from taf.selenium.sbts_fsm3.pages import bts_status
from taf.selenium.sbts_fsm3.pages import v23r4
from .modals import ResetModalCommonOperation, BlockCellModal


class BtsStatus(v23r4.BtsStatus):

    def __init__(self, driver):
        super(BtsStatus, self).__init__(driver)
        self._site_view = SiteViewPage(driver)
        self._detailed_site_view = DetailedSiteViewPage(driver)
        self._cells = CellsPage(driver)


class SiteViewPage(v23r4.bts_status.SiteViewPage):

    def __init__(self, driver):
        super(SiteViewPage, self).__init__(driver)
        self._view_panel = SiteViewPageViewPanel(driver)
        self._detail_panel = SiteViewPageDetailPanel(driver)


class SiteViewPageViewPanel(v23r4.bts_status.SiteViewPageViewPanel):

    def __init__(self, driver):
        super(SiteViewPageViewPanel, self).__init__(driver)
        self._detail_panel = SiteViewPageDetailPanel(driver)


class SiteViewPageDetailPanel(bts_status.SiteViewPageDetailPanel):

    def reset_hardware(self, with_graceful, timeout):
        self.wait_until_element_is_clickable(self._RESET_BUTTON_XPATH, timeout=timeout)
        ResetModalCommonOperation(self.driver).click_reset_and_confirm(with_graceful, self._RESET_BUTTON_XPATH)


class DetailedSiteViewPage(bts_status.DetailedSiteViewPage):
    """
    As a class will be called by BtsStatus, all operations on Detailed Site View will be implemented under this class.
    """

    def __init__(self, driver):
        super(DetailedSiteViewPage, self).__init__(driver)
        self._view_panel = DetailedSiteViewPageViewPanel(driver)
        self._detail_panel = DetailedSiteViewPageDetailPanel(driver)


class DetailedSiteViewPageViewPanel(bts_status.DetailedSiteViewPageViewPanel):

    def reset_site(self, with_graceful=False, without_radio_reset=False):
        ResetModalCommonOperation(self.driver).click_reset_and_confirm(
            with_graceful, self._RESET_SITE_BUTTON_XPATH, without_radio_reset=without_radio_reset)


class DetailedSiteViewPageDetailPanel(bts_status.DetailedSiteViewPageDetailPanel):

    def reset_hardware(self, with_graceful, timeout):
        self.wait_until_element_is_clickable(self._RESET_BUTTON_XPATH, timeout=timeout)
        ResetModalCommonOperation(self.driver).click_reset_and_confirm(with_graceful, self._RESET_BUTTON_XPATH)


class CellsPage(bts_status.CellsPage):

    def __init__(self, driver):
        super(CellsPage, self).__init__(driver)
        self._detail_panel = CellsPageDetailPanel(driver)


class CellsPageDetailPanel(bts_status.CellsPageDetailPanel):

    def _change_cell_status_on_modal(self, state, with_graceful=False, timeout=60):
        cell_modal = BlockCellModal(self.driver)
        cell_modal.wait_until_block_cell_modal_appear(timeout)
        if state == self._LOCK_STATUS:
            cell_modal.lock(timeout)
        elif state == self._UNLOCK_STATUS:
            cell_modal.unlock(timeout)
        elif state == self._RESET_STATUS:
            cell_modal.reset(with_graceful, timeout)
